import{_ as e,o as r,c as o,a2 as d}from"./chunks/framework.UsESEDQP.js";const m=JSON.parse('{"title":"Troubleshooting: Common Errors","description":"Error messages and their solutions","frontmatter":{"title":"Troubleshooting: Common Errors","description":"Error messages and their solutions","audience":["operator","user"],"symptoms":["error message","exception","startup failure"]},"headers":[],"relativePath":"troubleshooting/common-errors.md","filePath":"troubleshooting/common-errors.md","lastUpdated":1775243555000}'),a={name:"troubleshooting/common-errors.md"};function i(s,t,n,c,h,l){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="common-errors" tabindex="-1">Common Errors <a class="header-anchor" href="#common-errors" aria-label="Permalink to &quot;Common Errors&quot;">​</a></h1><p>Error messages sorted by when they occur.</p><h2 id="startup-errors" tabindex="-1">Startup errors <a class="header-anchor" href="#startup-errors" aria-label="Permalink to &quot;Startup errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Failed to connect to homeserver</code></td><td>Homeserver unreachable at <code>bridge.url</code></td><td>Check URL, ensure homeserver is running, check network/firewall</td></tr><tr><td><code>Homeserver returned 403</code></td><td>Appservice registration rejected</td><td>Verify <code>as_token</code>/<code>hs_token</code> match in both registration.yml and homeserver config. Restart homeserver after adding registration.</td></tr><tr><td><code>This endpoint can only be called by appservices</code></td><td>Encryption enabled but appservice not recognized</td><td>Check registration file is loaded by homeserver. See <a href="https://github.com/matrix-org/matrix-hookshot/issues/1137" target="_blank" rel="noreferrer">#1137</a></td></tr><tr><td><code>ENOENT: no such file or directory, open &#39;...&#39;</code></td><td>Config references a file that doesn&#39;t exist</td><td>Check <code>passFile</code>, <code>github.auth.privateKeyFile</code> paths. Docker: ensure volumes are mounted correctly.</td></tr><tr><td><code>Config validation failed</code></td><td>Invalid config.yml</td><td>Run <code>yarn validate-config</code> for details</td></tr><tr><td><code>Could not decrypt token store</code></td><td>passkey.pem changed or corrupted</td><td>If key is lost, users must re-authenticate. Generate new key and restart.</td></tr></tbody></table><h2 id="webhook-errors" tabindex="-1">Webhook errors <a class="header-anchor" href="#webhook-errors" aria-label="Permalink to &quot;Webhook errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Webhook signature verification failed</code></td><td>Secret mismatch between hookshot and external service</td><td>Update <code>webhook.secret</code> in config to match the service&#39;s settings</td></tr><tr><td><code>No handler found for webhook</code></td><td>Webhook URL doesn&#39;t match any connection</td><td>Verify URL path. For generic webhooks, check hookId is valid.</td></tr><tr><td><code>waitForComplete timed out</code></td><td>Transformation function or processing took too long</td><td>Simplify transformation function. See <a href="https://github.com/matrix-org/matrix-hookshot/issues/1251" target="_blank" rel="noreferrer">#1251</a></td></tr><tr><td><code>Transformation function failed</code></td><td>JavaScript error in transformation code</td><td>Test function with simpler input. Check for syntax errors.</td></tr><tr><td><code>Static webhook setup with transformationFunction fails</code></td><td>QuickJS not initialized at startup for static connections</td><td>See <a href="https://github.com/matrix-org/matrix-hookshot/issues/1228" target="_blank" rel="noreferrer">#1228</a></td></tr></tbody></table><h2 id="matrix-message-errors" tabindex="-1">Matrix message errors <a class="header-anchor" href="#matrix-message-errors" aria-label="Permalink to &quot;Matrix message errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Failed to send event to room</code></td><td>Bot can&#39;t send to the room</td><td>Check bot is a member. Check power levels. Check room isn&#39;t read-only.</td></tr><tr><td><code>M_FORBIDDEN</code></td><td>Bot lacks permission</td><td>Invite bot to room, or increase bot&#39;s power level</td></tr><tr><td><code>M_ROOM_NOT_FOUND</code></td><td>Room no longer exists</td><td>Connection is stale — remove it</td></tr><tr><td><code>Event too large</code></td><td>Message exceeds Matrix event size limit (65KB)</td><td>Large webhook payloads are trimmed automatically. If this persists, check transformation function output.</td></tr></tbody></table><h2 id="authentication-errors" tabindex="-1">Authentication errors <a class="header-anchor" href="#authentication-errors" aria-label="Permalink to &quot;Authentication errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>GitHub App authentication failed</code></td><td>Wrong App ID or invalid private key</td><td>Verify <code>github.auth.id</code> and <code>github.auth.privateKeyFile</code></td></tr><tr><td><code>OAuth state mismatch</code></td><td>Stale OAuth callback</td><td>Retry login flow</td></tr><tr><td><code>Token refresh failed</code></td><td>OAuth refresh token expired</td><td>User must re-authenticate</td></tr><tr><td><code>Invalid redirect_uri</code></td><td>Mismatch between config and service</td><td>Ensure exact match including trailing slash</td></tr></tbody></table><h2 id="connection-errors" tabindex="-1">Connection errors <a class="header-anchor" href="#connection-errors" aria-label="Permalink to &quot;Connection errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>You do not have permission to use this command</code></td><td>Insufficient permission level</td><td>Admin: check <code>permissions</code> config</td></tr><tr><td><code>Service is not configured</code></td><td>Trying to use a service not in config</td><td>Operator: add service section to config.yml</td></tr><tr><td><code>Connection already exists</code></td><td>Duplicate connection to same resource</td><td>Remove existing: <code>!hookshot list</code> then delete</td></tr><tr><td><code>Could not validate connection state</code></td><td>Invalid state event content</td><td>Check state event format matches expected schema</td></tr></tbody></table><h2 id="feed-errors" tabindex="-1">Feed errors <a class="header-anchor" href="#feed-errors" aria-label="Permalink to &quot;Feed errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Feed fetch failed</code></td><td>URL unreachable or returns invalid content</td><td>Verify URL is accessible from hookshot. Check it returns valid RSS/Atom.</td></tr><tr><td><code>Feed entries re-posted after restart</code></td><td>No Redis cache configured</td><td>Configure <code>cache.redisUri</code> to persist feed state</td></tr><tr><td><code>Display names resetting on upgrade</code></td><td>Bot profile reset on restart</td><td>See <a href="https://github.com/matrix-org/matrix-hookshot/issues/1149" target="_blank" rel="noreferrer">#1149</a></td></tr></tbody></table><h2 id="where-to-get-more-help" tabindex="-1">Where to get more help <a class="header-anchor" href="#where-to-get-more-help" aria-label="Permalink to &quot;Where to get more help&quot;">​</a></h2><ol><li>Set <code>logging.level: debug</code> and reproduce the error</li><li>Search <a href="https://github.com/matrix-org/matrix-hookshot/issues" target="_blank" rel="noreferrer">GitHub issues</a> for the error message</li><li>Ask in <a href="https://matrix.to/#/#hookshot:half-shot.uk" target="_blank" rel="noreferrer">#hookshot:half-shot.uk</a> with logs and config (redact secrets)</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Troubleshooting Index</a></li><li><a href="./webhooks-not-arriving">Webhooks Not Arriving</a></li><li><a href="./authentication">Authentication Issues</a></li><li><a href="./connection-issues">Connection Issues</a></li></ul>',18)])])}const b=e(a,[["render",i]]);export{m as __pageData,b as default};
